//! Golden-value determinism tests. Outputs are compared bit-for-bit.
//!
//! EXCEPT for the PCG32 reference vector (taken from the PCG C reference
//! `pcg32-demo`, seed 42 / stream 54), every golden value below was
//! GENERATED BY THIS IMPLEMENTATION (run once, then frozen). They are not
//! external references: they exist to catch any change in output, on any
//! platform, compiler or optimisation level. If a change is intentional,
//! regenerate them and bump the crate version.

use re_noise::*;

const P2: [(f32, f32); 3] = [(0.5, 0.25), (-3.7, 12.9), (101.31, -57.03)];
const P3: [(f32, f32, f32); 3] = [(0.5, 0.25, 0.75), (-3.7, 12.9, 4.4), (101.31, -57.03, 9.87)];
const SEED: u64 = 42;

fn check2(name: &str, f: impl Fn(f32, f32) -> f32, want: [u32; 3]) {
    for (&(x, y), w) in P2.iter().zip(want) {
        let got = f(x, y).to_bits();
        assert_eq!(got, w, "{name}({x}, {y}): got {got:#010x}, want {w:#010x}");
    }
}

fn check3(name: &str, f: impl Fn(f32, f32, f32) -> f32, want: [u32; 3]) {
    for (&(x, y, z), w) in P3.iter().zip(want) {
        let got = f(x, y, z).to_bits();
        assert_eq!(
            got, w,
            "{name}({x}, {y}, {z}): got {got:#010x}, want {w:#010x}"
        );
    }
}

#[test]
fn pcg32_reference_vector() {
    // External reference: pcg32-demo, pcg32_srandom_r(&rng, 42u, 54u).
    let mut r = Pcg32::new(42, 54);
    let want = [
        0xa15c02b7, 0x7b47f409, 0xba1d3330, 0x83d2f293, 0xbfa4784b, 0xcbed606e,
    ];
    for w in want {
        assert_eq!(r.next_u32(), w);
    }
}

#[test]
fn rng_goldens() {
    let mut sm = SplitMix64::new(0);
    assert_eq!(sm.next_u64(), 0xe220a8397b1dcdaf);
    assert_eq!(sm.next_u64(), 0x6e789e6aa1b965f4);
    assert_eq!(sm.next_u64(), 0x06c45d188009454f);

    let mut r = Pcg32::from_seed(1234);
    assert_eq!(
        [r.next_u32(), r.next_u32(), r.next_u32()],
        [0x67f2c675, 0x32f69c91, 0x711a5dd4]
    );
    assert_eq!(r.next_u64(), 0x5b132a8b4f6488e8);
    assert_eq!(r.next_f32().to_bits(), 0x3ebe0d76);
    assert_eq!(r.next_f64().to_bits(), 0x3fa9a7823076e1b0);
    assert_eq!(r.range_u32(10, 1000), 697);

    let mut c = Pcg32::new(42, 54).fork(7);
    assert_eq!([c.next_u32(), c.next_u32()], [0x8e88cb95, 0xd420d991]);

    assert_eq!(hash2(SEED, -3, 7), 0xedf1b80f);
    assert_eq!(hash3(SEED, -3, 7, 11), 0x009b8381);
}

#[test]
fn gradient_goldens() {
    check2(
        "perlin2",
        |x, y| perlin2(SEED, x, y),
        [0xbf1d98af, 0x3eea6fed, 0x3e270df3],
    );
    check3(
        "perlin3",
        |x, y, z| perlin3(SEED, x, y, z),
        [0x3d5e612e, 0xbee469f3, 0x3e6a29a3],
    );
    check2(
        "simplex2",
        |x, y| simplex2(SEED, x, y),
        [0x3f1dd881, 0x3eb7ef0e, 0xbe8c0e5e],
    );
    check3(
        "simplex3",
        |x, y, z| simplex3(SEED, x, y, z),
        [0xbc666626, 0xbddeb38b, 0xbdd3707a],
    );
}

#[test]
fn fractal_goldens() {
    let f = Fractal::default();
    let fs = Fractal {
        basis: Basis::Simplex,
        ..f
    };
    check2(
        "fbm2",
        |x, y| fbm2(SEED, &f, x, y),
        [0xbdf0214b, 0x3a413396, 0x3d82f21f],
    );
    check3(
        "fbm3",
        |x, y, z| fbm3(SEED, &fs, x, y, z),
        [0xbe16596c, 0xbe2a9e27, 0x3e9db287],
    );
    check2(
        "ridged2",
        |x, y| ridged2(SEED, &f, x, y),
        [0x3f0f19d6, 0x3efea226, 0x3f0c6a59],
    );
    check3(
        "ridged3",
        |x, y, z| ridged3(SEED, &fs, x, y, z),
        [0x3f17888e, 0x3ee7d8cb, 0x3e1a40a1],
    );
    check2(
        "warped2",
        |x, y| warped_fbm2(SEED, &f, 0.8, x, y),
        [0xbdefbfc1, 0xbc0dd21e, 0x3e1bad3b],
    );
    check3(
        "warped3",
        |x, y, z| warped_fbm3(SEED, &fs, 0.8, x, y, z),
        [0x3ee21a54, 0x3c6a1947, 0x3f1ef4d3],
    );
}

#[test]
fn cellular_goldens() {
    let want2 = [
        (0x3f4fed2d, 0x3f6faf28, 0xcd32f5bb),
        (0x3eb04fdc, 0x3f524273, 0xb73c9b7d),
        (0x3e899209, 0x3f537509, 0x812557ee),
    ];
    for (&(x, y), w) in P2.iter().zip(want2) {
        let c = cellular2(SEED, x, y);
        assert_eq!(
            (c.f1.to_bits(), c.f2.to_bits(), c.id),
            w,
            "cellular2({x}, {y})"
        );
    }
    let want3 = [
        (0x3f575841, 0x3f5c2054, 0xcd32f5bb),
        (0x3f1323db, 0x3f538928, 0x416a7b9b),
        (0x3f2ebcf7, 0x3f4a4ca5, 0x40843e6e),
    ];
    for (&(x, y, z), w) in P3.iter().zip(want3) {
        let c = cellular3(SEED, x, y, z);
        assert_eq!(
            (c.f1.to_bits(), c.f2.to_bits(), c.id),
            w,
            "cellular3({x}, {y}, {z})"
        );
    }
}
